  IntPtr Hook(IntPtr hwnd,int msg,IntPtr wp,IntPtr lp,ref bool handled){if(msg==0x24){handled=ApplyMaximizedWorkArea988(hwnd,lp);return IntPtr.Zero;}if(msg==0x312){int id=wp.ToInt32();if(id==HotkeyId){handled=true;ToggleStart();}else if(id==989){handled=true;profile.HudVisible=!profile.HudVisible;Save();var task=SetHud("HUD",profile.HudVisible);if(page=="main")ShowMain();}else if(id==990){handled=true;profile.HudDetails=!profile.HudDetails;Save();var task=SetHud("DETAIL",profile.HudDetails);if(page=="main")ShowMain();}}return IntPtr.Zero;}
  void LatchFault(string message){faulted=true;counting=false;ClearTelemetry();engine.Trace("FAULT_LATCH "+message);SetNotice(message+" 请查看会话记录；确认后才能再次开始。");status.Text="本次会话异常停止";UpdateControls();}
  void ToggleStart(bool explicitButton=false){if(quitting)return;var exited=engine.ObserveExit();if(exited!=null&&(running||exited.Unexpected)){running=false;LatchFault("引擎已退出（"+exited.ExitCode+"）。");return;}if(counting){counting=false;status.Text="已取消";UpdateControls();return;}if(operating)return;if(running){StopCapture();return;}if(faulted){if(!explicitButton||engine.HasProcess){SetNotice("异常已锁定。请打开主窗口检查记录，再点击“确认后恢复”。");return;}faulted=false;communicationFailures=0;engine.Trace("FAULT_ACK explicit button; no START issued");SetNotice("");status.Text="已恢复 · 可再次开始";UpdateControls();return;}SetNotice("");counting=true;countdownUntil=Stopwatch.GetTimestamp()+(long)(Stopwatch.Frequency*settings.CountdownSeconds);status.Text="请切回游戏 · "+settings.CountdownSeconds+" 秒";UpdateControls();}
  bool Matches(Profile p,WindowTarget target){if(!p.AutoSelect||string.IsNullOrWhiteSpace(p.Filter))return false;foreach(string piece in p.Filter.Split(';')){if(string.IsNullOrWhiteSpace(piece))continue;string pattern="^"+Regex.Escape(piece.Trim()).Replace("\\*",".*").Replace("\\?",".")+"$";foreach(string value in new[]{target.Title,target.ExecutablePath,Path.GetFileName(target.ExecutablePath??"")})if(Regex.IsMatch(value??"",pattern,RegexOptions.IgnoreCase))return true;}return false;}
  async Task BeginStart(){operationEpoch++;sessionStartQpc=Stopwatch.GetTimestamp()/(double)Stopwatch.Frequency;ClearTelemetry();counting=false;operating=true;status.Text="准备插帧引擎…";UpdateControls();Exception failure=null;bool startAttempted=false;try{
   var foreground=GetAncestor(GetForegroundWindow(),2);WindowTarget target=selectedTarget;
   if(target==null||target.Handle==IntPtr.Zero)target=WindowCatalog.List(Process.GetCurrentProcess().Id).FirstOrDefault(w=>w.Handle==foreground);
   if(target==null||!WindowCatalog.IsCurrent(target))throw new InvalidOperationException("请让游戏保持可见，并在游戏内按 "+settings.Hotkey+"。" );
   if(target.Handle!=foreground)throw new InvalidOperationException("倒计时结束时目标游戏不在前台，请切回游戏后按快捷键。" );
   var matched=settings.Profiles.FirstOrDefault(p=>Matches(p,target));if(matched!=null){profile=matched;settings.SelectedProfileId=profile.Id;Save();RefreshProfiles();}
   startAttempted=true;await engine.StartAsync(target,profile);running=true;communicationFailures=0;lastEngineState="preparing";status.Text="准备中 · "+target.Title;tray.Text="Smooth Motion · 准备中";
  }catch(Exception e){failure=e;ReportError(e);}
   try{if(failure!=null){if(startAttempted){LatchFault("启动未能确认："+failure.Message);await CleanupFault();}else running=false;}}finally{operating=false;UpdateControls();}
  }
  async Task CleanupFault(){try{await engine.ShutdownAsync();}catch(Exception ex){engine.Trace("fault cleanup "+ex);SetNotice("清理尚未完成："+ex.Message+"；禁止重新启动。");}running=engine.HasProcess;ClearTelemetry();}
  async void StopCapture(){if(operating)return;operationEpoch++;ClearTelemetry();operating=true;status.Text="正在安全停止…";UpdateControls();bool failed=false;
   try{await engine.StopAsync();running=false;status.Text="已停止 · 可再次开始";tray.Text="Smooth Motion · 就绪";}catch(Exception e){ReportError(e);failed=true;LatchFault("安全停止未能确认："+e.Message);}
   try{if(failed)await CleanupFault();}finally{operating=false;UpdateControls();}
  }
  long lastPoll,operationEpoch;double sessionStartQpc;async void Tick(object sender,EventArgs args){if(quitting)return;if(counting){double remain=(countdownUntil-Stopwatch.GetTimestamp())/(double)Stopwatch.Frequency;if(remain<=0){await BeginStart();}else{start.Content="取消 "+Math.Ceiling(remain);status.Text="请切回游戏 · "+Math.Ceiling(remain)+" 秒";}return;}long now=Stopwatch.GetTimestamp();if(now-lastPoll<Stopwatch.Frequency||polling||operating)return;lastPoll=now;
   var exited=engine.ObserveExit();if(exited!=null){bool wasRunning=running;running=false;ClearTelemetry();if(wasRunning||exited.Unexpected)LatchFault("插帧引擎已退出（"+exited.ExitCode+"）。");else{status.Text="就绪";UpdateControls();}}
   if(!engine.HasProcess)return;
   polling=true;long requestEpoch=operationEpoch;bool cleanup=false;try{var state=await engine.CommandAsync("STATUS");if(requestEpoch!=operationEpoch||operating||quitting)return;communicationFailures=0;if(state.EmergencyHotkeyKnown&&!state.EmergencyHotkeyRegistered&&!faulted)SetNotice("紧急停止快捷键被其他程序占用；请使用本程序停止按钮或开始 / 停止快捷键。");if(lastEngineState!=state.State)engine.Trace("STATE "+lastEngineState+" -> "+state.State+" safeIdle="+state.SafeIdle);AcceptEngineState990(state,Stopwatch.GetTimestamp()/(double)Stopwatch.Frequency);
    if(state.State=="error"){LatchFault(state.Message.Length>0?state.Message:state.Error);cleanup=true;}else if(!faulted){status.Text=StateText(state);status.ToolTip=state.Message;}if(state.SafeIdle)tray.Text="Smooth Motion · 就绪";else tray.Text="Smooth Motion · "+(state.State=="paused"?"已暂停":state.State=="wait_foreground"?"等待游戏":state.State=="preparing"?"准备中":"插帧中");UpdateControls();UpdateTelemetry();
   }catch(Exception e){if(requestEpoch==operationEpoch&&!operating&&!quitting){communicationFailures++;engine.Trace("IPC_FAILURE "+communicationFailures+" "+e.Message);SetNotice("引擎暂未响应："+e.Message);status.Text="正在等待引擎";ClearTelemetry();if(fullscreenText!=null)fullscreenText.Text="状态不可用";if(communicationFailures>=3){LatchFault("引擎连续三次未响应，正在结束本次会话。");cleanup=true;}}}finally{polling=false;}
   if(cleanup&&!operating&&!quitting){operating=true;operationEpoch++;UpdateControls();try{await CleanupFault();}finally{operating=false;UpdateControls();}}
  }
  void AcceptEngineState990(EngineReply state,double nowQpc){if(state.State=="running"&&lastEngineState!="running"){sessionStartQpc=Math.Max(sessionStartQpc,nowQpc);ClearTelemetry();}lastEngineState=state.State;running=!state.SafeIdle;}
  string StateText(EngineReply r){if(r.SafeIdle&&r.PauseReason990=="closed")return"游戏已退出 · 已停止";switch(r.State){case"running":return"插帧中";case"wait_foreground":return"模型已就绪 · 请切回游戏，等待期间不插帧";case"preparing":return r.PreparationStage992=="capture_setup"?"模型已就绪 · 准备捕获与显示 "+r.CaptureSetupSeconds992.ToString("F0")+" 秒":"准备模型与校验 "+r.ModelPreparationSeconds992.ToString("F0")+" 秒";case"paused":switch(r.PauseReason990){case"focus":return"游戏失焦 · 已暂停，等待回到游戏";case"minimized":return"游戏已最小化 · 已暂停";case"obscured":return"游戏被遮挡 · 已暂停";case"hidden":return"游戏窗口隐藏 · 已暂停";case"closed":return"游戏已退出 · 正在安全停止";default:return"已暂停 · 等待游戏恢复前台";}case"stopping":return"正在安全停止…";case"error":return"本次会话已停止";default:return r.ModelRetained?"就绪 · 模型已保留":"就绪";}}
  void UpdateTargetStatus990(){if(fullscreenText==null)return;var r=engine.Last;if(faulted){fullscreenText.Text="状态不可用";return;}if(!running){fullscreenText.Text=r.PauseReason990=="closed"?"游戏已退出":"等待启动后检测";return;}if(!r.TargetInfoValid990){fullscreenText.Text="窗口几何暂不可用";return;}fullscreenText.Text=r.TargetFullscreen990?"已检测到无边框全屏":"窗口模式 · 覆盖 "+r.Coverage990.ToString("P0");fullscreenText.ToolTip="目标客户区 "+r.TargetClientWidth990+" × "+r.TargetClientHeight990+"；显示器 "+r.TargetMonitorWidth990+" × "+r.TargetMonitorHeight990+"。覆盖值仅表示几何面积比例，非内容或实际扫描测量。";}

  void UpdateControls(){start.Content=counting?"取消倒计时":operating?(running?"停止中…":"准备中…"):running?"停止插帧":faulted?"确认后恢复":"开始插帧";start.IsEnabled=!operating;profiles.IsEnabled=!Active;edit.IsEnabled=remove.IsEnabled=!Active&&profile!=settings.Profiles[0];if(targetBox!=null)targetBox.IsEnabled=!Active;foreach(var c in sessionControls)c.IsEnabled=!Active&&!(c.Tag is string&&(string)c.Tag=="unavailable");}
  static string Number(double value){return double.IsNaN(value)||double.IsInfinity(value)?"—":value.ToString("0.0");}
  void ClearTelemetry(){if(fpsText!=null){fpsText.Text="— FPS";splitText.Text="等待有效展示数据";lowText.Text="1% low —";powerText.Text="GPU 驱动域 — W   ·   封装 — W";}}
  void UpdateTelemetry(){if(page!="main"||fpsText==null)return;UpdateTargetStatus990();UpdateGeometry992();if(faulted||!running||lastEngineState!="running"){ClearTelemetry();if(!faulted&&running&&(lastEngineState=="paused"||lastEngineState=="wait_foreground"))splitText.Text=StateText(engine.Last);return;}var m=TelemetryReader.Read(engine.TelemetryPath);if(Stopwatch.GetTimestamp()/(double)Stopwatch.Frequency-m.AgeSeconds<sessionStartQpc){ClearTelemetry();return;}bool good=m.Available&&!m.Stale&&(m.DisplayValid||m.IsLowerBound);fpsText.Text=good?(m.IsLowerBound?"≥ ":"")+Number(m.DisplayFps)+" FPS":"— FPS";splitText.Text=good?"原生 "+Number(m.NativeFps)+"  ·  生成 "+Number(m.GeneratedFps)+"  ·  覆盖 "+m.Coverage.ToString("P0"):"等待有效展示数据";lowText.Text="1% low "+(good&&m.Low1Valid?Number(m.Low1Fps):"—");powerText.Text="GPU 驱动域 "+(!m.Stale&&m.GpuPowerValid?Number(m.GpuPowerWatts):"—")+" W   ·   封装 "+(!m.Stale&&m.PackagePowerValid?Number(m.PackagePowerWatts):"—")+" W";powerText.ToolTip="GPU 域："+m.GpuPowerDomain+"\n封装："+m.PackagePowerDomain+"\n均非插帧独占功耗；GPU 域未校准。";}
  void InitTray(){using(var iconStream=Assembly.GetExecutingAssembly().GetManifestResourceStream("AppIcon989.ico")){if(iconStream!=null)using(var sourceIcon=new System.Drawing.Icon(iconStream)){trayIcon=(System.Drawing.Icon)sourceIcon.Clone();}}tray=new Forms.NotifyIcon{Icon=trayIcon??System.Drawing.SystemIcons.Application,Text="Smooth Motion · 就绪",Visible=true};var menu=new Forms.ContextMenuStrip();menu.Items.Add("打开 Smooth Motion",null,(s,e)=>Dispatcher.BeginInvoke(new Action(Restore)));menu.Items.Add("停止插帧",null,(s,e)=>Dispatcher.BeginInvoke(new Action(()=>{if(counting){counting=false;UpdateControls();}else StopCapture();})));menu.Items.Add(new Forms.ToolStripSeparator());menu.Items.Add("停止并退出",null,(s,e)=>Dispatcher.BeginInvoke(new Action(async()=>await ExitAsync())));tray.ContextMenuStrip=menu;tray.DoubleClick+=(s,e)=>Dispatcher.BeginInvoke(new Action(Restore));}
  public void Restore(){Show();if(WindowState==WindowState.Minimized)WindowState=WindowState.Normal;Activate();}
  void OpenLogs(){Directory.CreateDirectory(Path.Combine(engine.DataDir,"sessions"));Process.Start("explorer.exe",engine.SessionDir??Path.Combine(engine.DataDir,"sessions"));}
  async Task ExitAsync(){if(quitting)return;quitting=true;counting=false;operating=true;status.Text="正在停止并退出…";UpdateControls();await Task.Yield();try{await engine.ShutdownAsync();}catch(Exception e){engine.Trace(e.ToString());SetNotice("引擎清理尚未完成："+e.Message);}finally{if(engine.HasProcess){quitting=false;operating=false;running=true;LatchFault("引擎仍未退出，请使用停止按钮。");}else{allowClose=true;Close();}}}

